 "content": "from collections import deque


def transform(grid):
    """Keep and repair large near-solid rectangular objects; discard scattered noise."""
    h, w = len(grid), len(grid[0])
    # The uniform field is the canvas/background color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = [[False] * w for _ in range(h)]
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            box_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            density = len(cells) / box_area
            # Task objects are substantial filled rectangles with occasional
            # single-cell distractors replacing their true color.
            if box_area >= 12 and density >= 0.65:
                objects.append((color, min_r, max_r, min_c, max_c))

    out = [[background for _ in range(w)] for _ in range(h)]
    for color, min_r, max_r, min_c, max_c in objects:
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                out[r][c] = color
    return out
